export function parseModifyVoteOverrideInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedModifyVoteOverrideInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      signer: getNextAccount(),
      proposal: getNextAccount(),
      validatorVote: getNextAccount(),
      splVoteAccount: getNextAccount(),
      voteOverride: getNextAccount(),
      voteOverrideCache: getNextAccount(),
      splStakeAccount: getNextAccount(),
      snapshotProgram: getNextAccount(),
      consensusResult: getNextAccount(),
      metaMerkleProof: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getModifyVoteOverrideInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
